Method.Source:
/// <summary>
/// This method used for populating a value to the METPillar computed coloumn.
/// </summary>
/// <returns>The value of the <c>Piller dimension value</c> </returns>
public static str GetPillarDimension()
{
    str DefaultDimension = SysComputedColumn::returnField(
        tableStr(VendProductReceiptHeaderEntity),
        identifierStr(PurchTable),
        fieldStr(PurchTable, DefaultDimension));

    str pillarDimension = '(select di.DISPLAYVALUE from DIMENSIONATTRIBUTEVALUESETITEM di ' +
    'JOIN DimensionAttributeValue ON di.DimensionAttributeValue = DimensionAttributeValue.RecId ' +
    'JOIN DimensionAttribute ON DimensionAttribute.RecId = DimensionAttributeValue.DimensionAttribute ' +
    'where di.DIMENSIONATTRIBUTEVALUESET = ' + DefaultDimension + ' and DimensionAttribute.NAME = \'Pillar\')';

    return pillarDimension;
}

/// <summary>
/// This method used for populating a value to the METETrade computed coloumn.
/// </summary>
/// <returns>The value of the <c>ETrade value</c> </returns>
public static str getEtrade()
{
    str eTrade; 
    str orderAccount =  SysComputedColumn::returnField(
        tableStr(VendProductReceiptHeaderEntity),
        identifierStr(VendPackingSlipJour),
        fieldStr(VendPackingSlipJour, OrderAccount));

    str siteId = SysComputedColumn::returnField(
        tableStr(VendProductReceiptHeaderEntity),
        identifierStr(PurchTable),
        fieldStr(PurchTable, InventSiteId));

    str locationId = SysComputedColumn::returnField(
        tableStr(VendProductReceiptHeaderEntity),
        identifierStr(PurchTable),
        fieldStr(PurchTable, InventLocationId));

    eTrade =strFmt("(select top 1 ETradeSetting from METVendSiteSettingsSetup where AssignedVendorAccount = %1 and AssignedSite = %2 and AssignedWH = %3)",
    orderAccount, siteId, locationId);

    return eTrade;

}
